<?php
namespace App\Services;
use App\Core\{Database,Auth};
final class RecurringService {
    public static function generateDue(int $tenantId): int {$db=Database::connection();$count=0;$db->beginTransaction();try{$s=$db->prepare("SELECT * FROM maintenance_schedules WHERE tenant_id=? AND active=1 AND auto_create_job=1 AND next_run_at<=NOW() FOR UPDATE");$s->execute([$tenantId]);foreach($s->fetchAll() as $r){$num=NumberService::next($tenantId,'job','JOB');$desc='Preventive maintenance generated from schedule #'.$r['id'];$db->prepare("INSERT INTO jobs(tenant_id,job_number,customer_id,asset_id,description,priority,scheduled_date,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,'Normal',?,'Scheduled',?,NOW(),NOW())")->execute([$tenantId,$num,$r['customer_id'],$r['asset_id']?:null,$desc,$r['next_run_at'],Auth::id()]);$next=self::nextDate($r['frequency_type'],$r['next_run_at']);$db->prepare("UPDATE maintenance_schedules SET last_run_at=?,next_run_at=?,updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([$r['next_run_at'],$next,$r['id'],$tenantId]);$count++;}$rj=$db->prepare("SELECT * FROM recurring_jobs WHERE tenant_id=? AND active=1 AND next_run_at<=NOW() FOR UPDATE");$rj->execute([$tenantId]);foreach($rj->fetchAll() as $r){$num=NumberService::next($tenantId,'job','JOB');$db->prepare("INSERT INTO jobs(tenant_id,job_number,customer_id,site_id,asset_id,service_category,description,priority,scheduled_date,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'Normal',?,'Scheduled',?,NOW(),NOW())")->execute([$tenantId,$num,$r['customer_id'],$r['site_id']?:null,$r['asset_id']?:null,$r['service_category'],$r['description']?:$r['title'],$r['next_run_at'],Auth::id()]);$next=self::nextDate(self::normalizeRule($r['recurrence_rule']),$r['next_run_at']);$db->prepare("UPDATE recurring_jobs SET last_run_at=?,next_run_at=?,updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([$r['next_run_at'],$next,$r['id'],$tenantId]);$count++;}$db->commit();return $count;}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
    private static function normalizeRule(string $r):string{$r=strtolower(trim($r));return match(true){str_contains($r,'week')=>'Weekly',str_contains($r,'3 month')=>'Every 3 Months',str_contains($r,'6 month')=>'Every 6 Months',str_contains($r,'year')||str_contains($r,'annual')=>'Annual',default=>'Monthly'};}
    private static function nextDate(string $freq,string $from):string{$map=['Weekly'=>'+1 week','Monthly'=>'+1 month','Every 3 Months'=>'+3 months','Every 6 Months'=>'+6 months','Annual'=>'+1 year'];return date('Y-m-d H:i:s',strtotime($map[$freq]??'+1 month',strtotime($from)));}
}
